"""Explicit causal mask admits maintained KV repetition and efficient SDPA.

Torch 2.12.1 uses CUTLASS OpMultiplyAddFastF32 for float/SM80 attention.
FP32 tensors and process IEEE GEMM settings do not make this arithmetic IEEE.
https://github.com/pytorch/pytorch/blob/v2.12.1/aten/src/ATen/native/transformers/cuda/mem_eff_attention/gemm_kernel_utils.h
"""

from __future__ import annotations

from dataclasses import dataclass
from typing import cast

import torch
from torch import nn
from torch.nn.attention import SDPBackend, sdpa_kernel
from transformers.modeling_outputs import BaseModelOutputWithPast
from transformers.models.qwen3.modeling_qwen3 import Qwen3Model

from benchmarks.analysis.cuda.scorer import FP32Scorer, require_fp32
from wyat.backends.kai.encoding import EncodedRequest
from wyat.backends.kai.torch import CandidateHead, KaiScorer
from wyat.core import Request


class MaskedBackbone(nn.Module):
    """One existing backbone owner; fresh square full-prefill mask per call.

    The original model/config is unchanged. No cache, registry mutation or
    backend fallback is permitted. HF performs the KV repetition itself.
    """

    def __init__(self, model: Qwen3Model) -> None:
        super().__init__()
        if (
            any(module.training for module in model.modules())
            or model.has_sliding_layers
            or model.config._attn_implementation != "sdpa"
        ):
            raise ValueError("Efficient candidate requires eval full attention")
        self.model = model
        self.training = False

    def forward(
        self, *, input_ids: torch.Tensor, use_cache: bool
    ) -> BaseModelOutputWithPast:
        if (
            use_cache is not False
            or input_ids.ndim != 2
            or input_ids.dtype != torch.long
        ):
            raise ValueError("Efficient candidate requires uncached 2D token IDs")
        length = input_ids.shape[1]
        if length == 0:
            raise ValueError("Efficient candidate requires nonempty token IDs")
        positions = torch.arange(length, device=input_ids.device)
        mask = (positions[:, None] >= positions[None, :])[None, None]
        # This nested context deliberately overrides FP32Scorer's math control.
        with sdpa_kernel(SDPBackend.EFFICIENT_ATTENTION):
            return cast(
                BaseModelOutputWithPast,
                self.model(input_ids=input_ids, attention_mask=mask, use_cache=False),
            )


@dataclass(frozen=True)
class ScorerView:
    """Only the fields consumed by the immutable FP32Scorer boundary."""

    base: KaiScorer
    backbone: MaskedBackbone

    @property
    def head(self) -> CandidateHead:
        return self.base.head

    @property
    def device(self) -> torch.device:
        return self.base.device

    @property
    def pad_id(self) -> int:
        return self.base.pad_id

    def encode_request(self, request: Request) -> EncodedRequest:
        return self.base.encode_request(request)


def efficient_scorer(base: KaiScorer) -> FP32Scorer:
    require_fp32(base)
    view = ScorerView(base, MaskedBackbone(base.backbone))
    # The frozen research API names KaiScorer nominally but consumes only this
    # typed view's encoder/device/pad/head/module-call contract. Do not change
    # its old source or misrepresent the adapter as a Qwen3Model subclass.
    return FP32Scorer(cast(KaiScorer, view))

"""Diagnostic dispatch metadata only; never attach to ordinary inference."""

from __future__ import annotations

import warnings
from collections.abc import Sequence
from typing import Protocol, cast

import torch
from torch._C._autograd import DeviceType
from torch.profiler import ProfilerActivity, profile
from torch.utils._python_dispatch import TorchDispatchMode

from benchmarks.analysis.cuda.manifest import MODEL_ID
from wyat import Model
from wyat.benchmark import BenchmarkCycle, BenchmarkEngine, _run
from wyat.core import Scorer
from wyat.evaluation import EvaluationCase


class Operator(Protocol):
    def __call__(self, *args: object, **kwargs: object) -> object: ...


def tensor_metadata(value: torch.Tensor) -> dict[str, object]:
    return {
        "shape": list(value.shape),
        "stride": list(value.stride()),
        "dtype": str(value.dtype),
        "device": str(value.device),
    }


def argument(
    args: tuple[object, ...],
    kwargs: dict[str, object],
    position: int,
    name: str,
    default: object = None,
) -> object:
    return args[position] if len(args) > position else kwargs.get(name, default)


def call_flags(
    args: tuple[object, ...], kwargs: dict[str, object]
) -> dict[str, object]:
    """Pinned public SDPA schema; keep no tensor references in diagnostics."""
    values = {
        "dropout_p": argument(args, kwargs, 4, "dropout_p", 0.0),
        "is_causal": argument(args, kwargs, 5, "is_causal", False),
        "scale": kwargs.get("scale"),
        "enable_gqa": kwargs.get("enable_gqa", False),
    }
    return {
        name: value
        if value is None or isinstance(value, (bool, float, int))
        else f"unsupported scalar type: {type(value).__name__}"
        for name, value in values.items()
    }


# Upstream TorchDispatchMode.__init_subclass__ lacks annotations.
class Dispatch(TorchDispatchMode):  # type: ignore[no-untyped-call]
    """Keep primitives only; do not extend any attention tensor lifetime."""

    def __init__(self) -> None:
        super().__init__()  # type: ignore[no-untyped-call]  # upstream initializer
        self.events: list[dict[str, object]] = []

    def __torch_dispatch__(
        self,
        func: object,
        types: tuple[type[object], ...],
        args: tuple[object, ...] = (),
        kwargs: dict[str, object] | None = None,
    ) -> object:
        name = str(func)
        options = {} if kwargs is None else kwargs
        if "scaled_dot_product" in name:
            inputs = [
                argument(args, options, index, field)
                for index, field in enumerate(("query", "key", "value", "attn_mask"))
            ]
            tensors = [value for value in inputs if isinstance(value, torch.Tensor)]
            event: dict[str, object] = {
                "operator": name,
                "tensors": [tensor_metadata(value) for value in tensors],
            }
            if name == "aten.scaled_dot_product_attention.default":
                flags = call_flags(args, options)
                event.update(
                    call_flags=flags,
                    selector_boundary="public_before_bias_conversion",
                    selector_scale_scope=(
                        "SDPAParams has no scale field; explicit scales are not queried"
                    ),
                    converted_bias_strides="unknown",
                )
                dropout = flags["dropout_p"]
                causal, gqa = flags["is_causal"], flags["enable_gqa"]
                if (
                    len(tensors) == 4
                    and type(dropout) in (float, int)
                    and isinstance(causal, bool)
                    and isinstance(gqa, bool)
                    and flags["scale"] is None
                ):
                    try:
                        params = torch.backends.cuda.SDPAParams(
                            tensors[0],
                            tensors[1],
                            tensors[2],
                            tensors[3],
                            float(cast(float, dropout)),
                            causal,
                            gqa,
                        )
                        event["efficient_eligible"] = (
                            torch.backends.cuda.can_use_efficient_attention(
                                params, debug=True
                            )
                        )
                    except (RuntimeError, ValueError) as error:
                        event["selector_error"] = str(error)
                else:
                    event["selector_error"] = (
                        "SDPAParams cannot represent this call's scalar arguments "
                        "or explicit scale"
                    )
            self.events.append(event)
        # Operator overloads are an untyped upstream variadic callable boundary.
        return cast(Operator, func)(*args, **options)


def profile_batch(
    scorer: Scorer,
    cases: tuple[EvaluationCase, ...],
    *,
    name: str,
) -> tuple[BenchmarkCycle, dict[str, object]]:
    observer = Dispatch()
    with (
        warnings.catch_warnings(record=True) as caught,
        profile(
            activities=[ProfilerActivity.CPU, ProfilerActivity.CUDA], record_shapes=True
        ) as profiler,
        observer,
    ):
        cycle = _run(
            BenchmarkEngine(
                name, Model(scorer, model_id=MODEL_ID), batch_size=len(cases)
            ),
            cases,
        )
        torch.cuda.synchronize()
    events = profiler.key_averages(group_by_input_shape=True)
    kernels = [
        {
            "name": event.name,
            "duration_us": event.time_range.elapsed_us(),
            "device_index": event.device_index,
        }
        for event in profiler.events()
        if event.device_type == DeviceType.CUDA
    ]
    return cycle, {
        "case_ids": [case.id for case in cases],
        "dispatch": observer.events,
        "operators": [
            {
                "name": event.key,
                "count": event.count,
                "shapes": event.input_shapes,
                "self_cpu_time_us": event.self_cpu_time_total,
                "self_device_time_us": event.self_device_time_total,
            }
            for event in events
        ],
        "warnings": [str(item.message) for item in caught],
        "cuda_kernel_events": kernels,
        "cuda_kernel_names_available": bool(kernels),
        "timing_scope": "Intrusive profiler/dispatch diagnostics; no speed claim",
    }


def efficient_dispatch_gate(
    evidence: dict[str, object], *, batch_size: int, length: int
) -> bool:
    events = cast(Sequence[dict[str, object]], evidence.get("dispatch", ()))
    if len(events) != 28:
        return False
    expected = [batch_size, 16, length, 128]
    for event in events:
        flags = cast(dict[str, object], event.get("call_flags", {}))
        if (
            event.get("operator") != "aten.scaled_dot_product_attention.default"
            or event.get("selector_boundary") != "public_before_bias_conversion"
            or set(flags) != {"dropout_p", "is_causal", "enable_gqa", "scale"}
            or type(flags.get("dropout_p")) not in (float, int)
            or flags.get("dropout_p") != 0
            or flags.get("is_causal") is not False
            or flags.get("enable_gqa") is not False
            or (
                flags.get("scale") is not None
                and (
                    type(flags.get("scale")) is not float
                    or flags.get("scale") != 128**-0.5
                )
            )
        ):
            return False
        tensors = cast(list[dict[str, object]], event.get("tensors", []))
        if len(tensors) != 4:
            return False
        if any(
            value.get("shape") != expected
            or value.get("dtype") != "torch.float32"
            or not value.get("stride")
            or cast(list[int], value["stride"])[-1] != 1
            or value.get("device") != "cuda:0"
            for value in tensors[:3]
        ):
            return False
        # This is the actual public mask, preceding C++ bias conversion/padding.
        if (
            tensors[3].get("shape") != [1, 1, length, length]
            or tensors[3].get("dtype") != "torch.bool"
            or tensors[3].get("device") != "cuda:0"
            or tensors[3].get("stride") != [length * length, length * length, length, 1]
        ):
            return False
    operators = cast(Sequence[dict[str, object]], evidence.get("operators", ()))
    counts: dict[str, int] = {}
    for operator in operators:
        name, count = operator.get("name"), operator.get("count")
        if not isinstance(name, str) or type(count) is not int or count < 0:
            return False
        counts[name] = counts.get(name, 0) + count
    if (
        counts.get("aten::_scaled_dot_product_efficient_attention") != 28
        or counts.get("aten::_efficient_attention_forward") != 28
        or any(
            count > 0
            and any(
                fallback in name
                for fallback in ("attention_math", "flash_attention", "cudnn_attention")
            )
            for name, count in counts.items()
        )
    ):
        return False
    kernels = cast(Sequence[dict[str, object]], evidence.get("cuda_kernel_events", ()))
    attention_names = [
        name
        for event in kernels
        if isinstance(name := event.get("name"), str) and "fmha" in name.lower()
    ]
    # This exact runtime/device observed the SM80-specialized FP32 CUTLASS path.
    # Other implementations remain unsupported by this diagnostic declaration.
    return (
        evidence.get("cuda_kernel_names_available") is True
        and len(attention_names) == 28
        and all(
            name.startswith("fmha_cutlassF_f32_aligned_") and "_sm80(" in name
            for name in attention_names
        )
    )

"""Capture an actual maintained gate input, then detach it through host storage."""

from __future__ import annotations

import hashlib
import time
from collections.abc import Callable, Iterator
from contextlib import contextmanager
from dataclasses import dataclass
from typing import TYPE_CHECKING, Protocol, cast

import numpy as np

from wyat.benchmark import BenchmarkCycle, BenchmarkEngine, _run
from wyat.core import Model
from wyat.evaluation import EvaluationCase

if TYPE_CHECKING:
    import mlx.core as mx

    from wyat.backends.kai.mlx import MLXKaiScorer
    from wyat.backends.kai.prefix import PrefixScorer


@dataclass(frozen=True, slots=True)
class CapturedInput:
    values: np.ndarray[tuple[int, int], np.dtype[np.float32]]
    cycle: BenchmarkCycle
    copy_elapsed_ms: float

    def metadata(self) -> dict[str, object]:
        return {
            "copy_materialization_elapsed_ms": self.copy_elapsed_ms,
            "shape": list(self.values.shape),
            "dtype": str(self.values.dtype),
            "host_strides_bytes": list(self.values.strides),
            "sha256": hashlib.sha256(self.values.tobytes()).hexdigest(),
            "nbytes": self.values.nbytes,
        }


class CaptureFailure(ValueError):
    def __init__(self, message: str, cycle: BenchmarkCycle) -> None:
        super().__init__(message)
        self.cycle = cycle


class CaptureProjection:
    """Call the unchanged projection and observe its exact argument once."""

    def __init__(self, original: Callable[[mx.array], mx.array]) -> None:
        self.original = original
        self.inputs: list[mx.array] = []

    def __call__(self, value: mx.array) -> mx.array:
        self.inputs.append(value)
        return self.original(value)


class ProjectionOwner(Protocol):
    gate_proj: Callable[[mx.array], mx.array]


@contextmanager
def observe_projection(owner: ProjectionOwner) -> Iterator[CaptureProjection]:
    original = owner.gate_proj
    observer = CaptureProjection(original)
    owner.gate_proj = observer
    try:
        yield observer
    finally:
        owner.gate_proj = original


def detached_float32(
    value: mx.array,
) -> np.ndarray[tuple[int, int], np.dtype[np.float32]]:
    """A host-owned copy cannot retain a lazy model graph or checkpoint owner."""
    import mlx.core as mx

    if value.dtype != mx.float32 or len(value.shape) not in (2, 3):
        raise ValueError("Capture requires a rank2/3 FP32 activation")
    mx.eval(value)
    host = np.array(value, dtype=np.float32, copy=True).reshape(-1, value.shape[-1])
    if not np.isfinite(host).all():
        raise ValueError("Actual capture contains nonfinite activations")
    return np.ascontiguousarray(host)


def capture_input(
    base: MLXKaiScorer,
    scorer: MLXKaiScorer | PrefixScorer,
    cases: tuple[EvaluationCase, ...],
    *,
    batch_size: int,
    expected_rows: int,
) -> CapturedInput:
    """One declared batch only; prefix construction must precede this hook."""
    if not cases or len(cases) != batch_size:
        raise ValueError("Capture requires one complete declared batch")
    with observe_projection(
        cast(ProjectionOwner, base.backbone.layers[0].mlp)
    ) as observer:
        cycle = _run(
            BenchmarkEngine(
                "actual-activation-capture", Model(scorer, base.model_id), batch_size
            ),
            cases,
        )
        if cycle.failed or len(observer.inputs) != 1:
            raise CaptureFailure(
                "Capture did not visit exactly one successful gate call", cycle
            )
        started = time.perf_counter_ns()
        values = detached_float32(observer.inputs[0])
        copy_elapsed_ms = (time.perf_counter_ns() - started) / 1e6
        if values.shape != (expected_rows, 1024):
            raise CaptureFailure(
                "Actual projection input differs from declared geometry", cycle
            )
    return CapturedInput(values, cycle, copy_elapsed_ms)


def exact_bfloat_bits(
    values: np.ndarray[tuple[int, int], np.dtype[np.float32]],
) -> bool:
    """BF16 decode preserves FP32 bits, including the sign of zero."""
    return bool(
        np.isfinite(values).all() and np.all((values.view(np.uint32) & 0xFFFF) == 0)
    )


def projection_quality(
    reference: np.ndarray[tuple[int, int], np.dtype[np.float32]],
    candidate: np.ndarray[tuple[int, int], np.dtype[np.float32]],
) -> dict[str, object]:
    if (
        reference.shape != candidate.shape
        or reference.dtype != candidate.dtype
        or reference.dtype != np.float32
    ):
        raise ValueError("Projection quality requires matching FP32 shapes")
    finite = bool(np.isfinite(reference).all() and np.isfinite(candidate).all())
    difference = np.abs(candidate.astype(np.float64) - reference.astype(np.float64))
    failures = (~np.isfinite(difference)) | (
        difference > 1e-4 + 1e-4 * np.abs(reference.astype(np.float64))
    )
    return {
        "passed": finite and not bool(failures.any()),
        "finite": finite,
        "failing_elements": int(failures.sum()),
        "total_elements": reference.size,
        "max_abs_error": float(difference.max()) if finite else None,
        "atol": 1e-4,
        "rtol": 1e-4,
    }

"""One fixed tile policy: float SIMD arithmetic with independent weight storage.

Preparation checks actual device strides without asking MLX to copy inputs.
Only the public custom Metal API and Metal SIMD matrix operations are used.
This experiment does not replace production matmul.
"""

from collections.abc import Sequence
from dataclasses import dataclass
from typing import Protocol, cast

import mlx.core as mx

TILE = 32
THREADS = 128
SHARED_BYTES = 3 * TILE * TILE * 4
HEADER = """
#include <metal_simdgroup>
#include <metal_simdgroup_matrix>
"""
SOURCE = """
const uint M = X_shape[0];
const uint K = X_shape[1];
const uint N = W_shape[0];
const uint tid = thread_index_in_threadgroup;
const uint group = simdgroup_index_in_threadgroup;
const uint row_start = threadgroup_position_in_grid.y * 32;
const uint col_start = threadgroup_position_in_grid.x * 32;
const uint group_row = (group / 2) * 16;
const uint group_col = (group % 2) * 16;

threadgroup float x_tile[1024];
threadgroup float w_tile[1024];
threadgroup float output_tile[1024];
simdgroup_float8x8 accumulators[4];
for (uint i = 0; i < 4; ++i) {
    accumulators[i] = make_filled_simdgroup_matrix<float, 8, 8>(0.0f);
}

for (uint start = 0; start < K; start += 32) {
    for (uint i = tid; i < 1024; i += 128) {
        const uint local_row = i / 32;
        const uint local_col = i % 32;
        const uint row = row_start + local_row;
        const uint col = col_start + local_row;
        const uint reduction = start + local_col;
        x_tile[i] = (row < M && reduction < K)
            ? float(X[size_t(row) * K + reduction]) : 0.0f;
        // Stage W.T in float; no complete FP32 weight allocation.
        w_tile[local_col * 32 + local_row] = (col < N && reduction < K)
            ? float(W[size_t(col) * K + reduction]) : 0.0f;
    }
    threadgroup_barrier(mem_flags::mem_threadgroup);
    for (uint reduction = 0; reduction < 32; reduction += 8) {
        simdgroup_float8x8 a[2];
        simdgroup_float8x8 b[2];
        for (uint i = 0; i < 2; ++i) {
            simdgroup_load(a[i], x_tile + (group_row + i * 8) * 32
                + reduction, 32);
            simdgroup_load(b[i], w_tile + reduction * 32
                + group_col + i * 8, 32);
        }
        for (uint row = 0; row < 2; ++row) {
            for (uint col = 0; col < 2; ++col) {
                const uint i = row * 2 + col;
                simdgroup_multiply_accumulate(accumulators[i], a[row], b[col],
                    accumulators[i]);
            }
        }
    }
    // No thread overwrites staged operands before every SIMD group finishes.
    threadgroup_barrier(mem_flags::mem_threadgroup);
}

for (uint row = 0; row < 2; ++row) {
    for (uint col = 0; col < 2; ++col) {
        simdgroup_store(accumulators[row * 2 + col], output_tile
            + (group_row + row * 8) * 32 + group_col + col * 8, 32);
    }
}
threadgroup_barrier(mem_flags::mem_threadgroup);
for (uint i = tid; i < 1024; i += 128) {
    const uint row = row_start + i / 32;
    const uint col = col_start + i % 32;
    if (row < M && col < N) {
        Y[size_t(row) * N + col] = output_tile[i];
    }
}
"""

LAYOUT_SOURCE = """
if (thread_position_in_grid.x == 0) {
    layout[0] = X_strides[0];
    layout[1] = X_strides[1];
    layout[2] = W_strides[0];
    layout[3] = W_strides[1];
}
"""


class MetalKernel(Protocol):
    def __call__(
        self,
        *,
        inputs: Sequence[mx.array],
        grid: tuple[int, int, int],
        threadgroup: tuple[int, int, int],
        output_shapes: Sequence[tuple[int, ...]],
        output_dtypes: Sequence[mx.Dtype],
    ) -> list[mx.array]: ...


@dataclass(frozen=True)
class PreparedProjection:
    """Validated inputs held ready; run excludes preparation and layout dispatch."""

    x: mx.array
    weight: mx.array
    kernel: MetalKernel

    def run(self) -> mx.array:
        rows, _ = self.x.shape
        columns, _ = self.weight.shape
        return self.kernel(
            inputs=[self.x, self.weight],
            grid=(
                THREADS * ((columns + TILE - 1) // TILE),
                (rows + TILE - 1) // TILE,
                1,
            ),
            threadgroup=(THREADS, 1, 1),
            output_shapes=[(rows, columns)],
            output_dtypes=[mx.float32],
        )[0]


class ProjectionKernel:
    """Build once; MLX compiles specializations lazily on evaluated dispatch."""

    def __init__(self) -> None:
        self._projection = cast(
            MetalKernel,
            mx.fast.metal_kernel(
                name="wyat_mixed_projection",
                input_names=["X", "W"],
                output_names=["Y"],
                source=SOURCE,
                header=HEADER,
                ensure_row_contiguous=False,
                compile_options={"math_mode": "safe"},
            ),
        )
        self._layout = cast(
            MetalKernel,
            mx.fast.metal_kernel(
                name="wyat_mixed_layout",
                input_names=["X", "W"],
                output_names=["layout"],
                source=LAYOUT_SOURCE,
                ensure_row_contiguous=False,
                compile_options={"math_mode": "safe"},
            ),
        )

    def prepare(self, x: mx.array, weight: mx.array) -> PreparedProjection:
        if x.dtype != mx.float32 or weight.dtype not in (mx.float32, mx.bfloat16):
            raise ValueError("Projection requires FP32 X and FP32 or BF16 W")
        if x.ndim != 2 or weight.ndim != 2:
            raise ValueError("Projection requires rank-two X[M,K] and W[N,K]")
        if any(d <= 0 or d > 2**31 - 1 for d in (*x.shape, *weight.shape)):
            raise ValueError("Projection dimensions must be positive int32 values")
        if x.shape[1] != weight.shape[1]:
            raise ValueError("Projection reduction dimensions differ")
        layout = self._layout(
            inputs=[x, weight],
            grid=(1, 1, 1),
            threadgroup=(1, 1, 1),
            output_shapes=[(4,)],
            output_dtypes=[mx.int64],
        )[0]
        mx.eval(layout)
        observed = cast(list[int], layout.tolist())
        expected = [x.shape[1], 1, weight.shape[1], 1]
        if observed != expected:
            raise ValueError(f"Projection requires row-contiguous inputs: {observed}")
        return PreparedProjection(x, weight, self._projection)

"""Read-only admission of the audited initial projection and exact captured bytes."""

from __future__ import annotations

import hashlib
from dataclasses import dataclass
from pathlib import Path

from wyat.backends.kai.artifact import load_artifact
from wyat.wire import JsonObject, JsonValue, read_object

ROOT = Path(__file__).resolve().parents[4]
INITIAL = ROOT / "benchmarks/analysis/results/mlx-mixed-gate.json"
REVIEW = INITIAL.with_name("mlx-mixed-gate-review.json")
VERIFICATION = ROOT / "benchmarks/real/mlx-mixed-tooling-verification.json"
IDENTITIES = {
    INITIAL: "fb8bde4a9a7d0c5b24c40a67183f582dc46c56c8d3ccbb79461d87065c023b8c",
    REVIEW: "08d8b0bd6f60b8f24a2374a1ead6a43cc32d0228d10c77b3f714379314c9e985",
    VERIFICATION: "e332f2fafda3712eca17f5637cc0490165349021a7f7b826432e84e0c7cd681b",
}
DOC = "docs/analysis/mixed.md"
DOC_SHA256 = "ab0ce4e460dd7614e6ee63a5bf839671902b446ccb9bb26044c33218d29d0f59"


def object_value(value: JsonValue) -> JsonObject:
    if not isinstance(value, dict):
        raise ValueError("Expected object")
    return value


def string(value: JsonValue) -> str:
    if not isinstance(value, str):
        raise ValueError("Expected string")
    return value


def digest(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def checked_file(record: JsonValue) -> Path:
    entry = object_value(record)
    path = Path(string(entry["path"]))
    if digest(path) != string(entry["sha256"]):
        raise ValueError(f"Frozen artifact changed: {path.name}")
    return path


def archive(record: JsonValue, hashes: JsonObject, count: int) -> dict[str, Path]:
    """Archive text is immutable; only the named documentation may now differ."""
    value = read_object(checked_file(record))
    entries = value["files"]
    if not isinstance(entries, list) or len(entries) != count or len(hashes) != count:
        raise ValueError("Frozen source inventory changed")
    paths: dict[str, Path] = {}
    for part in entries:
        entry = object_value(part)
        name, text = string(entry["name"]), string(entry["text"])
        expected = string(entry["sha256"])
        if name in paths or hashlib.sha256(text.encode()).hexdigest() != expected:
            raise ValueError("Invalid archived source text or repeated name")
        if hashes.get(name) != expected:
            raise ValueError("Source archive differs from recorded inventory")
        path = Path(string(entry["path"]))
        if name == DOC and (
            digest(path) != DOC_SHA256 or not path.read_text().startswith(text)
        ):
            raise ValueError("Only the audited documentation append is admitted")
        if name != DOC and digest(path) != expected:
            raise ValueError(f"Frozen executable source changed: {name}")
        paths[name] = path
    if set(paths) != set(hashes):
        raise ValueError("Frozen source names changed")
    return paths


@dataclass(frozen=True, slots=True)
class Admission:
    initial: JsonObject
    inputs: Path
    cold: Path
    sources: dict[str, Path]


def admit(model: Path) -> Admission:
    for path, expected in IDENTITIES.items():
        if digest(path) != expected:
            raise ValueError(f"Frozen admission receipt changed: {path.name}")
    initial, review, verification = map(read_object, IDENTITIES)
    if (
        initial["completed"] is not True
        or initial["capture_quality_passed"] is not True
        or initial["projection_quality_passed"] is not True
        or review["audit_passed"] is not True
        or verification["completed"] is not True
    ):
        raise ValueError("Initial projection evidence is incomplete")
    sources = archive(
        initial["source_archive"], object_value(initial["source_hashes"]), 43
    )
    sources.update(
        archive(
            verification["source_archive"],
            object_value(verification["source_sha256"]),
            104,
        )
    )
    artifacts = object_value(review["artifacts"])
    for record in artifacts.values():
        checked_file(record)
    inputs, cold = (
        checked_file(initial["captured_bytes"]),
        checked_file(initial["cold_outputs"]),
    )
    if inputs != checked_file(artifacts["inputs"]) or cold != checked_file(
        artifacts["cold_outputs"]
    ):
        raise ValueError("Independent audit names different tensor artifacts")
    artifact = load_artifact(model, max_length=512)
    if artifact.model_id != initial["model_id"]:
        raise ValueError("Frozen checkpoint identity changed")
    for path, field in (
        (ROOT / "benchmarks/real/banking77-train-dev-menu6.jsonl", "dataset_sha256"),
        (ROOT / "benchmarks/real/torch-fp32-reference77.json", "reference_sha256"),
    ):
        if digest(path) != initial[field]:
            raise ValueError("Frozen data/reference identity changed")
    return Admission(initial, inputs, cold, sources)

"""One 64×64×32 output-reuse hypothesis, with the frozen admission contract.

Sixteen float SIMD accumulators per SIMD group and 32 KiB of shared storage
are explicit costs. The initial 32-tile implementation remains untouched.
"""

from dataclasses import dataclass
from typing import cast

import mlx.core as mx

from benchmarks.analysis.mlx.mixed.kernel import HEADER, MetalKernel
from benchmarks.analysis.mlx.mixed.kernel import ProjectionKernel as Admission

TILE = 64
REDUCTION = 32
THREADS = 128
SHARED_BYTES = (2 * TILE * REDUCTION + TILE * TILE) * 4
SOURCE = """
const uint M = X_shape[0];
const uint K = X_shape[1];
const uint N = W_shape[0];
const uint tid = thread_index_in_threadgroup;
const uint group = simdgroup_index_in_threadgroup;
const uint row_start = threadgroup_position_in_grid.y * 64;
const uint col_start = threadgroup_position_in_grid.x * 64;
const uint group_row = (group / 2) * 32;
const uint group_col = (group % 2) * 32;

threadgroup float x_tile[2048];
threadgroup float w_tile[2048];
threadgroup float output_tile[4096];
simdgroup_float8x8 accumulators[16];
for (uint i = 0; i < 16; ++i) {
    accumulators[i] = make_filled_simdgroup_matrix<float, 8, 8>(0.0f);
}

for (uint start = 0; start < K; start += 32) {
    for (uint i = tid; i < 2048; i += 128) {
        const uint local_row = i / 32;
        const uint local_col = i % 32;
        const uint row = row_start + local_row;
        const uint col = col_start + local_row;
        const uint reduction = start + local_col;
        x_tile[i] = (row < M && reduction < K)
            ? float(X[size_t(row) * K + reduction]) : 0.0f;
        // The weight storage changes; float staged operands do not.
        w_tile[local_col * 64 + local_row] = (col < N && reduction < K)
            ? float(W[size_t(col) * K + reduction]) : 0.0f;
    }
    threadgroup_barrier(mem_flags::mem_threadgroup);
    for (uint reduction = 0; reduction < 32; reduction += 8) {
        simdgroup_float8x8 a[4];
        simdgroup_float8x8 b[4];
        for (uint i = 0; i < 4; ++i) {
            simdgroup_load(a[i], x_tile + (group_row + i * 8) * 32
                + reduction, 32);
            simdgroup_load(b[i], w_tile + reduction * 64
                + group_col + i * 8, 64);
        }
        for (uint row = 0; row < 4; ++row) {
            for (uint col = 0; col < 4; ++col) {
                const uint i = row * 4 + col;
                simdgroup_multiply_accumulate(accumulators[i], a[row], b[col],
                    accumulators[i]);
            }
        }
    }
    threadgroup_barrier(mem_flags::mem_threadgroup);
}

for (uint row = 0; row < 4; ++row) {
    for (uint col = 0; col < 4; ++col) {
        simdgroup_store(accumulators[row * 4 + col], output_tile
            + (group_row + row * 8) * 64 + group_col + col * 8, 64);
    }
}
threadgroup_barrier(mem_flags::mem_threadgroup);
for (uint i = tid; i < 4096; i += 128) {
    const uint row = row_start + i / 64;
    const uint col = col_start + i % 64;
    if (row < M && col < N) {
        Y[size_t(row) * N + col] = output_tile[i];
    }
}
"""


@dataclass(frozen=True)
class PreparedProjection:
    """Ready immutable operands; no admission check or input copy inside run."""

    x: mx.array
    weight: mx.array
    kernel: MetalKernel

    def run(self) -> mx.array:
        rows, _ = self.x.shape
        columns, _ = self.weight.shape
        return self.kernel(
            inputs=[self.x, self.weight],
            grid=(
                THREADS * ((columns + TILE - 1) // TILE),
                (rows + TILE - 1) // TILE,
                1,
            ),
            threadgroup=(THREADS, 1, 1),
            output_shapes=[(rows, columns)],
            output_dtypes=[mx.float32],
        )[0]


class ProjectionKernel:
    """Share the live 32-tile control's public validator; compile lazily once."""

    def __init__(self, admission: Admission) -> None:
        self._admission = admission
        self._projection = cast(
            MetalKernel,
            mx.fast.metal_kernel(
                name="wyat_tile_projection",
                input_names=["X", "W"],
                output_names=["Y"],
                source=SOURCE,
                header=HEADER,
                ensure_row_contiguous=False,
                compile_options={"math_mode": "safe"},
            ),
        )

    def prepare(self, x: mx.array, weight: mx.array) -> PreparedProjection:
        admitted = self._admission.prepare(x, weight)
        return PreparedProjection(admitted.x, admitted.weight, self._projection)

"""Fixed64 reuse trial on admitted prior activations; no model recapture."""

from __future__ import annotations

import hashlib
import itertools
import os
import time
from collections.abc import Callable
from pathlib import Path
from typing import cast

import mlx.core as mx
import numpy as np
from safetensors.numpy import load, save_file

from benchmarks.analysis.evidence import freeze_sources
from benchmarks.analysis.mlx.endpoints import memory
from benchmarks.analysis.mlx.mixed.capture import (
    detached_float32,
    exact_bfloat_bits,
    projection_quality,
)
from benchmarks.analysis.mlx.mixed.kernel import ProjectionKernel as FrozenKernel
from benchmarks.analysis.mlx.mixed.study import ARMS as ORIGINAL_ARMS
from benchmarks.analysis.mlx.mixed.study import (
    SHAPES,
    output_digest,
    performance,
    restored_cache,
    save,
)

from .admit import IDENTITIES, ROOT, Admission, digest, object_value

type Array = np.ndarray[tuple[int, int], np.dtype[np.float32]]
type Operation = Callable[[], mx.array]
ARMS = ("maintained", "tile32-bf16", "tile64-bf16")
ORDERS = tuple(itertools.permutations(ARMS))
CONTROL = "tile64-fp32"


def read_arrays(admission: Admission) -> tuple[dict[str, Array], dict[str, Array]]:
    def consumed(path: Path, field: str) -> dict[str, Array]:
        raw = path.read_bytes()
        expected = object_value(admission.initial[field])["sha256"]
        if hashlib.sha256(raw).hexdigest() != expected:
            raise ValueError("Captured tensor artifact changed before consumption")
        return cast(dict[str, Array], load(raw))

    inputs = consumed(admission.inputs, "captured_bytes")
    cold = consumed(admission.cold, "cold_outputs")
    if set(inputs) != {"weight", *(name for name, _, _ in SHAPES)} or set(cold) != {
        name + "-" + arm for name, _, _ in SHAPES for arm in ORIGINAL_ARMS
    }:
        raise ValueError("Frozen tensor inventory changed")
    checks = [("weight", (3072, 1024), object_value(admission.initial["weight"]))]
    captures = object_value(admission.initial["captures"])
    checks.extend(
        (name, (rows, 1024), object_value(captures[name])) for name, _, rows in SHAPES
    )
    for name, shape, record in checks:
        value = inputs[name]
        if (
            value.dtype != np.float32
            or value.shape != shape
            or not np.isfinite(value).all()
            or hashlib.sha256(value.tobytes()).hexdigest() != record["sha256"]
        ):
            raise ValueError("Frozen input geometry or bytes changed")
    if not exact_bfloat_bits(inputs["weight"]):
        raise ValueError("Captured weight is not bitwise BF16 decodable")
    shapes = object_value(admission.initial["shapes"])
    for name, _, rows in SHAPES:
        hashes = object_value(object_value(shapes[name])["cold_output_sha256"])
        for arm in ORIGINAL_ARMS:
            value = cold[name + "-" + arm]
            if (
                value.dtype != np.float32
                or value.shape != (rows, 3072)
                or not np.isfinite(value).all()
                or hashlib.sha256(value.tobytes()).hexdigest() != hashes[arm]
            ):
                raise ValueError("Frozen cold outputs changed")
    return inputs, cold


def comparison(blocks: list[dict[str, object]], baseline: str) -> dict[str, object]:
    """Reuse the original six-permutation gate; keep32 comparison descriptive."""
    translated: list[dict[str, object]] = []
    original_orders = tuple(itertools.permutations(ORIGINAL_ARMS))
    for block, expected, original_order in zip(
        blocks, ORDERS, original_orders, strict=True
    ):
        if tuple(cast(list[str], block["order"])) != expected:
            raise ValueError("Balanced execution order changed")
        timings = cast(dict[str, list[int]], block["dispatch_ns"])
        if set(timings) != set(ARMS):
            raise ValueError("Missing timed arm")
        translated.append(
            {
                "order": list(original_order),
                "dispatch_ns": {
                    "maintained": timings[baseline],
                    "custom-fp32": timings["tile32-bf16"],
                    "custom-bf16": timings["tile64-bf16"],
                },
            }
        )
    report = performance(translated)
    if baseline != "maintained":
        report.pop("passed")
    return report


def timed_blocks(
    calls: dict[str, Operation],
    cold: dict[str, str],
    result: dict[str, object],
    progress: Callable[[], None],
) -> None:
    warm: dict[str, str] = {}
    for arm in ARMS:
        y = calls[arm]()
        mx.eval(y)
        mx.synchronize(mx.gpu)
        warm[arm] = output_digest(y)
        del y
    result["warm_output_sha256"] = warm
    progress()
    if warm != cold:
        raise ValueError("Warm outputs changed from cold")
    blocks: list[dict[str, object]] = []
    result["blocks"] = blocks
    for order in ORDERS:
        timings: dict[str, list[int]] = {}
        hashes: dict[str, list[str]] = {}
        block: dict[str, object] = {
            "order": list(order),
            "dispatch_ns": timings,
            "output_sha256": hashes,
            "completed": False,
            "outputs_reproduce_cold": False,
            "memory_before": memory(),
        }
        blocks.append(block)
        for arm in order:
            timings[arm], hashes[arm] = [], []
            for _ in range(10):
                mx.synchronize(mx.gpu)
                start = time.perf_counter_ns()
                y = calls[arm]()
                mx.eval(y)
                mx.synchronize(mx.gpu)
                timings[arm].append(time.perf_counter_ns() - start)
                hashes[arm].append(output_digest(y))
                del y
            progress()
        reproduced = all(
            value == cold[arm] for arm, values in hashes.items() for value in values
        )
        block.update(
            completed=True, outputs_reproduce_cold=reproduced, memory_after=memory()
        )
        progress()
        if not reproduced:
            raise ValueError("Timed outputs changed from cold")
    result["performance"] = comparison(blocks, "maintained")
    result["tile32_over_tile64"] = comparison(blocks, "tile32-bf16")
    progress()


def screen(
    calls: dict[str, Operation], original: dict[str, Array], name: str
) -> tuple[dict[str, object], dict[str, Array]]:
    values: dict[str, Array] = {}
    cold_ms: dict[str, float] = {}
    for arm, call in calls.items():
        mx.synchronize(mx.gpu)
        start = time.perf_counter_ns()
        y = call()
        mx.eval(y)
        mx.synchronize(mx.gpu)
        cold_ms[arm] = (time.perf_counter_ns() - start) / 1e6
        values[arm] = detached_float32(y)
        del y
    hashes = {
        arm: hashlib.sha256(value.tobytes()).hexdigest()
        for arm, value in values.items()
    }
    history = all(
        np.array_equal(
            values[arm].view(np.uint32), original[name + "-" + old].view(np.uint32)
        )
        for arm, old in (("maintained", "maintained"), ("tile32-bf16", "custom-bf16"))
    )
    storage = np.array_equal(
        values[CONTROL].view(np.uint32), values["tile64-bf16"].view(np.uint32)
    )
    quality = {
        arm: projection_quality(values["maintained"], values[arm])
        for arm in (*ARMS[1:], CONTROL)
    }
    result: dict[str, object] = {
        "cold_dispatch_ms": cold_ms,
        "cold_output_sha256": hashes,
        "original_cold_outputs_reproduced": history,
        "custom_storage_bitwise_equal": storage,
        "quality": quality,
        "passed": history
        and storage
        and all(gate["passed"] is True for gate in quality.values()),
        "blocks": [],
    }
    return result, values


def study(admission: Admission, output: Path) -> bool:
    if output.exists():
        raise FileExistsError("Preserve prior tile receipts")
    if os.environ.get("MLX_ENABLE_TF32") != "0":
        raise ValueError("Disable TF32 before importing MLX")
    payload: dict[str, object] = {
        "completed": False,
        "accepted": False,
        "phase": "admission",
        "scope": (
            "Archived first-layer gate projection only;8 development cases; "
            "no model recapture or complete inference claim"
        ),
        "protocol": {
            "shapes": SHAPES,
            "arms": ARMS,
            "cold_control": CONTROL,
            "orders": ORDERS,
            "dispatches_per_arm_block": 10,
            "warm_dispatches": 1,
            "cold_dispatches": 1,
            "timeout_seconds": 180,
            "cache_cap_bytes": 512 << 20,
            "atol": 1e-4,
            "rtol": 1e-4,
            "median_minimum": 1.05,
            "p05_exclusive_minimum": 1.0,
            "bitwise_storage_controls": True,
            "partial_receipt": (
                "Complete arms saved; interruption during ten dispatches "
                "leaves partial arm unknown"
            ),
            "observation": (
                "Every warm/timed output hashed outside its timer against cold; "
                "observations separate dispatches, not unobserved throughput"
            ),
        },
    }
    output.parent.mkdir(parents=True, exist_ok=True)
    save(output, payload)
    try:
        from .kernel import ProjectionKernel

        sources = {
            **admission.sources,
            **{
                str(path.relative_to(ROOT)): path
                for path in Path(__file__).parent.glob("*.py")
            },
        }
        sources["docs/analysis/tile.md"] = ROOT / "docs/analysis/tile.md"
        sources["tests/analysis/test_mlx_tile_protocol.py"] = (
            ROOT / "tests/analysis/test_mlx_tile_protocol.py"
        )
        sources["tests/analysis/test_mlx_tile_kernel.py"] = (
            ROOT / "tests/analysis/test_mlx_tile_kernel.py"
        )
        frozen = freeze_sources(sources, output)
        inputs, original = read_arrays(admission)
        payload.update(
            source_hashes=frozen.hashes(),
            source_archive=frozen.archive(),
            reused_inputs={
                "path": str(admission.inputs),
                "sha256": digest(admission.inputs),
            },
            prior_receipts={
                str(path): expected for path, expected in IDENTITIES.items()
            },
            initial_cold_outputs=admission.initial["cold_outputs"],
            model_id=admission.initial["model_id"],
            dataset_sha256=admission.initial["dataset_sha256"],
            reference_sha256=admission.initial["reference_sha256"],
            input_sha256=admission.initial["input_sha256"],
            device=mx.device_info(mx.gpu),
        )
        with restored_cache(payload), mx.stream(mx.gpu):
            fixed32 = FrozenKernel()
            fixed64 = ProjectionKernel(fixed32)
            w32 = mx.array(inputs["weight"], dtype=mx.float32)
            w16 = w32.astype(mx.bfloat16)
            mx.eval(w32, w16)
            if not np.array_equal(
                detached_float32(w16.astype(mx.float32)).view(np.uint32),
                inputs["weight"].view(np.uint32),
            ):
                raise ValueError("Device BF16 reconstruction changed weight bits")
            results: dict[str, dict[str, object]] = {}
            calls_by_shape: dict[str, dict[str, Operation]] = {}
            cold_values: dict[str, Array] = {}
            payload.update(phase="screen", shapes=results)
            for name, _, _ in SHAPES:
                x = mx.array(inputs[name], dtype=mx.float32)
                mx.eval(x)
                ready32 = fixed32.prepare(x, w16)
                ready64 = fixed64.prepare(x, w16)
                control = fixed64.prepare(x, w32)

                def maintained(x: mx.array = x) -> mx.array:
                    return x @ w32.T

                calls = {
                    "maintained": maintained,
                    "tile32-bf16": ready32.run,
                    "tile64-bf16": ready64.run,
                    CONTROL: control.run,
                }
                results[name], values = screen(calls, original, name)
                cold_values.update(
                    {name + "-" + arm: value for arm, value in values.items()}
                )
                calls_by_shape[name] = {arm: calls[arm] for arm in ARMS}
                save(output, payload)
            cold_path = output.with_suffix(".outputs.tensors.safetensors")
            if cold_path.exists():
                raise FileExistsError("Preserve cold outputs")
            save_file(cold_values, str(cold_path))
            payload["cold_outputs"] = {
                "path": str(cold_path),
                "sha256": digest(cold_path),
            }
            numerical = all(result["passed"] is True for result in results.values())
            payload["projection_quality_passed"] = numerical
            if numerical:
                if any(digest(Path(item.path)) != item.sha256 for item in frozen.files):
                    raise ValueError("Frozen trial sources changed")
                payload["phase"] = "timing"
                for name, _, _ in SHAPES:
                    hashes = cast(dict[str, str], results[name]["cold_output_sha256"])
                    timed_blocks(
                        calls_by_shape[name],
                        {arm: hashes[arm] for arm in ARMS},
                        results[name],
                        lambda: save(output, payload),
                    )
            payload.update(
                completed=True,
                phase="complete",
                accepted=numerical
                and all(
                    cast(dict[str, object], results[name].get("performance", {})).get(
                        "passed"
                    )
                    is True
                    for name in ("prefix-b1", "prefix-b8")
                ),
            )
    except BaseException as error:
        payload.update(
            completed=False, accepted=False, error=f"{type(error).__name__}: {error}"
        )
    finally:
        try:
            save(output, payload)
        except Exception as error:
            payload.update(
                completed=False,
                accepted=False,
                final_write_error=f"{type(error).__name__}: {error}",
            )
            save(output, payload)
    return payload["completed"] is True and payload["accepted"] is True

"""Request static fragment indexing without changing the 64-tile policy.

An unroll pragma is a compiler request, not evidence of removed spills.
The historical 32/64 policies remain untouched and executable controls.
"""

from typing import cast

import mlx.core as mx

from benchmarks.analysis.mlx.mixed.kernel import HEADER, MetalKernel
from benchmarks.analysis.mlx.tile.kernel import PreparedProjection
from benchmarks.analysis.mlx.tile.kernel import ProjectionKernel as Admission

SOURCE = """
const uint M = X_shape[0];
const uint K = X_shape[1];
const uint N = W_shape[0];
const uint tid = thread_index_in_threadgroup;
const uint group = simdgroup_index_in_threadgroup;
const uint row_start = threadgroup_position_in_grid.y * 64;
const uint col_start = threadgroup_position_in_grid.x * 64;
const uint group_row = (group / 2) * 32;
const uint group_col = (group % 2) * 32;

threadgroup float x_tile[2048];
threadgroup float w_tile[2048];
threadgroup float output_tile[4096];
simdgroup_float8x8 accumulators[16];
#pragma clang loop unroll(full)
for (uint i = 0; i < 16; ++i) {
    accumulators[i] = make_filled_simdgroup_matrix<float, 8, 8>(0.0f);
}

for (uint start = 0; start < K; start += 32) {
    for (uint i = tid; i < 2048; i += 128) {
        const uint local_row = i / 32;
        const uint local_col = i % 32;
        const uint row = row_start + local_row;
        const uint col = col_start + local_row;
        const uint reduction = start + local_col;
        x_tile[i] = (row < M && reduction < K)
            ? float(X[size_t(row) * K + reduction]) : 0.0f;
        // The weight storage changes; float staged operands do not.
        w_tile[local_col * 64 + local_row] = (col < N && reduction < K)
            ? float(W[size_t(col) * K + reduction]) : 0.0f;
    }
    threadgroup_barrier(mem_flags::mem_threadgroup);
    #pragma clang loop unroll(full)
    for (uint reduction = 0; reduction < 32; reduction += 8) {
        simdgroup_float8x8 a[4];
        simdgroup_float8x8 b[4];
        #pragma clang loop unroll(full)
        for (uint i = 0; i < 4; ++i) {
            simdgroup_load(a[i], x_tile + (group_row + i * 8) * 32
                + reduction, 32);
            simdgroup_load(b[i], w_tile + reduction * 64
                + group_col + i * 8, 64);
        }
        #pragma clang loop unroll(full)
        for (uint row = 0; row < 4; ++row) {
            #pragma clang loop unroll(full)
            for (uint col = 0; col < 4; ++col) {
                const uint i = row * 4 + col;
                simdgroup_multiply_accumulate(accumulators[i], a[row], b[col],
                    accumulators[i]);
            }
        }
    }
    threadgroup_barrier(mem_flags::mem_threadgroup);
}

#pragma clang loop unroll(full)
for (uint row = 0; row < 4; ++row) {
    #pragma clang loop unroll(full)
    for (uint col = 0; col < 4; ++col) {
        simdgroup_store(accumulators[row * 4 + col], output_tile
            + (group_row + row * 8) * 64 + group_col + col * 8, 64);
    }
}
threadgroup_barrier(mem_flags::mem_threadgroup);
for (uint i = tid; i < 4096; i += 128) {
    const uint row = row_start + i / 64;
    const uint col = col_start + i % 64;
    if (row < M && col < N) {
        Y[size_t(row) * N + col] = output_tile[i];
    }
}
"""


class ProjectionKernel:
    """Share prior 64-tile admission and ready dispatch; compile lazily once."""

    def __init__(self, admission: Admission) -> None:
        self._admission = admission
        self._projection = cast(
            MetalKernel,
            mx.fast.metal_kernel(
                name="wyat_unroll_projection",
                input_names=["X", "W"],
                output_names=["Y"],
                source=SOURCE,
                header=HEADER,
                ensure_row_contiguous=False,
                compile_options={"math_mode": "safe"},
            ),
        )

    def prepare(self, x: mx.array, weight: mx.array) -> PreparedProjection:
        admitted = self._admission.prepare(x, weight)
        return PreparedProjection(admitted.x, admitted.weight, self._projection)

"""Compare maintained, frozen64 and explicitly unrolled64 on exact prior inputs."""

from __future__ import annotations

import hashlib
import itertools
import os
import time
from collections.abc import Callable, Mapping
from pathlib import Path
from typing import cast

import mlx.core as mx
import numpy as np
from safetensors.numpy import load, save_file

from benchmarks.analysis.evidence import freeze_sources
from benchmarks.analysis.mlx.endpoints import memory
from benchmarks.analysis.mlx.mixed.capture import detached_float32, projection_quality
from benchmarks.analysis.mlx.mixed.kernel import ProjectionKernel as OriginalKernel
from benchmarks.analysis.mlx.mixed.study import (
    SHAPES,
    output_digest,
    restored_cache,
    save,
)
from benchmarks.analysis.mlx.tile.admit import ROOT, digest, object_value
from benchmarks.analysis.mlx.tile.kernel import ProjectionKernel as FrozenKernel
from benchmarks.analysis.mlx.tile.study import Array, Operation, read_arrays
from wyat.evaluation import percentile

from .run import PINNED, Context

ARMS = ("maintained", "tile64-bf16", "unroll64-bf16")
ORDERS = tuple(itertools.permutations(ARMS))
CONTROL = "unroll64-fp32"


def comparison(blocks: list[dict[str, object]], baseline: str) -> dict[str, object]:
    ratios: list[float] = []
    for block, expected in zip(blocks, ORDERS, strict=True):
        if tuple(cast(list[str], block["order"])) != expected:
            raise ValueError("Balanced execution order changed")
        timings = cast(dict[str, list[int]], block["dispatch_ns"])
        if set(timings) != set(ARMS) or any(
            len(values) != 10
            or any(type(value) is not int or value <= 0 for value in values)
            for values in timings.values()
        ):
            raise ValueError("Requires all30 positive timings per block")
        ratios.append(sum(timings[baseline]) / sum(timings[ARMS[2]]))
    median, p05 = percentile(ratios, 0.5), percentile(ratios, 0.05)
    report: dict[str, object] = {
        "paired_ratios": ratios,
        "paired_median": median,
        "paired_p05": p05,
    }
    if baseline == ARMS[0]:
        report["passed"] = median >= 1.05 and p05 > 1
    return report


def measure(
    calls: Mapping[str, Operation],
    cold: Mapping[str, str],
    result: dict[str, object],
    progress: Callable[[], None],
) -> None:
    """Fresh synchronized dispatches; output observations occur after each timer."""
    warm: dict[str, str] = {}
    for arm in ARMS:
        y = calls[arm]()
        mx.eval(y)
        mx.synchronize(mx.gpu)
        warm[arm] = output_digest(y)
        del y
    result["warm_output_sha256"] = warm
    progress()
    if warm != cold:
        raise ValueError("Warm outputs changed from cold")
    blocks: list[dict[str, object]] = []
    result["blocks"] = blocks
    for order in ORDERS:
        timings: dict[str, list[int]] = {}
        hashes: dict[str, list[str]] = {}
        block: dict[str, object] = {
            "order": list(order),
            "dispatch_ns": timings,
            "output_sha256": hashes,
            "completed": False,
            "outputs_reproduce_cold": False,
            "memory_before": memory(),
        }
        blocks.append(block)
        for arm in order:
            timings[arm], hashes[arm] = [], []
            for _ in range(10):
                mx.synchronize(mx.gpu)
                start = time.perf_counter_ns()
                y = calls[arm]()
                mx.eval(y)
                mx.synchronize(mx.gpu)
                timings[arm].append(time.perf_counter_ns() - start)
                hashes[arm].append(output_digest(y))
                del y
            progress()
        reproduced = all(
            value == cold[arm] for arm, values in hashes.items() for value in values
        )
        block.update(
            completed=True, outputs_reproduce_cold=reproduced, memory_after=memory()
        )
        progress()
        if not reproduced:
            raise ValueError("Timed outputs changed from cold")
    result["performance"] = comparison(blocks, ARMS[0])
    result["tile64_over_unroll64"] = comparison(blocks, ARMS[1])
    progress()


def previous_outputs(context: Context) -> dict[str, Array]:
    raw = context.cold.read_bytes()
    if (
        hashlib.sha256(raw).hexdigest()
        != object_value(context.prior["cold_outputs"])["sha256"]
    ):
        raise ValueError("Frozen64 output artifact changed before consumption")
    arrays = cast(dict[str, Array], load(raw))
    prior_arms = ("maintained", "tile32-bf16", "tile64-bf16", "tile64-fp32")
    if set(arrays) != {name + "-" + arm for name, _, _ in SHAPES for arm in prior_arms}:
        raise ValueError("Frozen64 output inventory changed")
    for name, _, rows in SHAPES:
        hashes = object_value(
            object_value(object_value(context.prior["shapes"])[name])[
                "cold_output_sha256"
            ]
        )
        for arm in prior_arms:
            value = arrays[name + "-" + arm]
            if (
                value.dtype != np.float32
                or value.shape != (rows, 3072)
                or not np.isfinite(value).all()
                or hashlib.sha256(value.tobytes()).hexdigest() != hashes[arm]
            ):
                raise ValueError("Frozen64 output tensor changed")
    return arrays


def screen(
    calls: Mapping[str, Operation], original: Mapping[str, Array], name: str
) -> tuple[dict[str, object], dict[str, Array]]:
    values: dict[str, Array] = {}
    cold_ms: dict[str, float] = {}
    for arm, call in calls.items():
        mx.synchronize(mx.gpu)
        start = time.perf_counter_ns()
        y = call()
        mx.eval(y)
        mx.synchronize(mx.gpu)
        cold_ms[arm] = (time.perf_counter_ns() - start) / 1e6
        values[arm] = detached_float32(y)
        del y
    reproduced = all(
        np.array_equal(
            values[arm].view(np.uint32), original[name + "-" + arm].view(np.uint32)
        )
        for arm in ARMS[:2]
    )
    storage_equal = np.array_equal(
        values[CONTROL].view(np.uint32), values[ARMS[2]].view(np.uint32)
    )
    quality = {
        arm: projection_quality(values[ARMS[0]], values[arm])
        for arm in (*ARMS[1:], CONTROL)
    }
    return {
        "cold_dispatch_ms": cold_ms,
        "cold_output_sha256": {
            arm: hashlib.sha256(value.tobytes()).hexdigest()
            for arm, value in values.items()
        },
        "original_cold_outputs_reproduced": reproduced,
        "custom_storage_bitwise_equal": storage_equal,
        "quality": quality,
        "passed": reproduced
        and storage_equal
        and all(gate["passed"] is True for gate in quality.values()),
        "blocks": [],
    }, values


def study(context: Context, output: Path) -> bool:
    if output.exists():
        raise FileExistsError("Preserve prior unroll receipts")
    if os.environ.get("MLX_ENABLE_TF32") != "0":
        raise ValueError("Disable TF32 before importing MLX")
    payload: dict[str, object] = {
        "completed": False,
        "accepted": False,
        "phase": "admission",
        "scope": (
            "Exact archived first-layer gate projection; no model recapture "
            "or complete inference speed claim"
        ),
        "protocol": {
            "shapes": SHAPES,
            "arms": ARMS,
            "cold_control": CONTROL,
            "orders": ORDERS,
            "dispatches_per_arm_block": 10,
            "warm_dispatches": 1,
            "cold_dispatches": 1,
            "timeout_seconds": 180,
            "cache_cap_bytes": 512 << 20,
            "atol": 1e-4,
            "rtol": 1e-4,
            "median_minimum": 1.05,
            "p05_exclusive_minimum": 1.0,
            "bitwise_storage_controls": True,
            "partial_receipt": (
                "Complete arms saved; interruption during ten dispatches "
                "leaves partial arm unknown"
            ),
            "observation": (
                "Every warm/timed output hashed after its timer; "
                "observations separate dispatches, not unobserved throughput"
            ),
        },
    }
    output.parent.mkdir(parents=True, exist_ok=True)
    save(output, payload)
    try:
        from .kernel import ProjectionKernel

        sources = {
            **context.sources,
            **{
                str(path.relative_to(ROOT)): path
                for path in Path(__file__).parent.glob("*.py")
            },
        }
        sources.update(
            {
                name: ROOT / name
                for name in (
                    "docs/analysis/unroll.md",
                    "pyproject.toml",
                    "tests/analysis/test_mlx_unroll_protocol.py",
                    "tests/analysis/test_mlx_unroll_kernel.py",
                )
            }
        )
        frozen = freeze_sources(sources, output)
        inputs, obsolete_cold = read_arrays(context.original)
        del obsolete_cold
        original = previous_outputs(context)
        payload.update(
            source_hashes=frozen.hashes(),
            source_archive=frozen.archive(),
            reused_inputs={
                "path": str(context.original.inputs),
                "sha256": digest(context.original.inputs),
            },
            prior_receipts={str(path): sha for path, sha in PINNED.items()},
            prior_cold_outputs=context.prior["cold_outputs"],
            **{
                field: context.prior[field]
                for field in (
                    "model_id",
                    "dataset_sha256",
                    "reference_sha256",
                    "input_sha256",
                )
            },
            device=mx.device_info(mx.gpu),
        )
        with restored_cache(payload), mx.stream(mx.gpu):
            frozen64 = FrozenKernel(OriginalKernel())
            unroll64 = ProjectionKernel(frozen64)
            w32 = mx.array(inputs["weight"], dtype=mx.float32)
            w16 = w32.astype(mx.bfloat16)
            mx.eval(w32, w16)
            if not np.array_equal(
                detached_float32(w16.astype(mx.float32)).view(np.uint32),
                inputs["weight"].view(np.uint32),
            ):
                raise ValueError("Device BF16 reconstruction changed weight bits")
            results: dict[str, dict[str, object]] = {}
            operations: dict[str, dict[str, Operation]] = {}
            cold_values: dict[str, Array] = {}
            payload.update(phase="screen", shapes=results)
            for name, _, _ in SHAPES:
                x = mx.array(inputs[name], dtype=mx.float32)
                mx.eval(x)
                ready_old = frozen64.prepare(x, w16)
                ready_new = unroll64.prepare(x, w16)
                control = unroll64.prepare(x, w32)

                def maintained(x: mx.array = x) -> mx.array:
                    return x @ w32.T

                calls = {
                    ARMS[0]: maintained,
                    ARMS[1]: ready_old.run,
                    ARMS[2]: ready_new.run,
                    CONTROL: control.run,
                }
                results[name], values = screen(calls, original, name)
                cold_values.update(
                    {name + "-" + arm: value for arm, value in values.items()}
                )
                operations[name] = {arm: calls[arm] for arm in ARMS}
                save(output, payload)
            cold_path = output.with_suffix(".outputs.tensors.safetensors")
            if cold_path.exists():
                raise FileExistsError("Preserve cold outputs")
            save_file(cold_values, str(cold_path))
            payload["cold_outputs"] = {
                "path": str(cold_path),
                "sha256": digest(cold_path),
            }
            numerical = all(result["passed"] is True for result in results.values())
            payload["projection_quality_passed"] = numerical
            if numerical:
                if any(digest(Path(item.path)) != item.sha256 for item in frozen.files):
                    raise ValueError("Frozen trial source changed")
                payload["phase"] = "timing"
                for name, _, _ in SHAPES:
                    hashes = cast(dict[str, str], results[name]["cold_output_sha256"])
                    measure(
                        operations[name],
                        {arm: hashes[arm] for arm in ARMS},
                        results[name],
                        lambda: save(output, payload),
                    )
            payload.update(
                completed=True,
                phase="complete",
                accepted=numerical
                and all(
                    cast(dict[str, object], results[name].get("performance", {})).get(
                        "passed"
                    )
                    is True
                    for name in ("prefix-b1", "prefix-b8")
                ),
            )
    except BaseException as error:
        payload.update(
            completed=False, accepted=False, error=f"{type(error).__name__}: {error}"
        )
    finally:
        try:
            save(output, payload)
        except Exception as error:
            payload.update(
                completed=False,
                accepted=False,
                final_write_error=f"{type(error).__name__}: {error}",
            )
            save(output, payload)
    return payload["completed"] is True and payload["accepted"] is True

"""Exact CPU FP32 prefix state; maintained cached model and full final block."""

from __future__ import annotations

from collections.abc import Sequence
from typing import Protocol, cast

import torch
from transformers import Qwen3Config
from transformers.cache_utils import DynamicCache, DynamicLayer
from transformers.modeling_outputs import BaseModelOutputWithPast

from wyat.backends.kai.encoding import EncodedRequest
from wyat.backends.kai.torch import KaiScorer
from wyat.core import Request

type KVState = tuple[torch.Tensor, torch.Tensor]


class CacheConstructor(Protocol):
    def __call__(
        self,
        *,
        config: Qwen3Config,
        ddp_cache_data: tuple[KVState, ...] | None = None,
    ) -> DynamicCache: ...


# The maintained cache constructor is untyped; narrow this external boundary.
new_cache = cast(CacheConstructor, DynamicCache)


class PrefixScorer:
    """Fixed weights/config/device/encoder for one immutable prefix lifetime.

    Each invocation owns its DynamicCache. Seeding and suffix updates concatenate
    into private storage; no suffix state survives the invocation. Callers must
    keep the base in eval mode and never mutate its weights, config or encoder.
    Mismatched/overlapping batches fall back intact, including admission checks.
    """

    def __init__(self, base: KaiScorer, prefix: tuple[int, ...]) -> None:
        if not isinstance(base, KaiScorer):
            raise TypeError("CPU prefix requires a KaiScorer base")
        if type(prefix) is not tuple:
            raise TypeError("Prefix must be an exact immutable token tuple")
        config = base.backbone.config
        rotary = config.rope_parameters
        if (
            not isinstance(rotary, dict)
            or rotary.get("rope_type", "default") != "default"
        ):
            raise ValueError("CPU prefix requires default unscaled RoPE")
        if (
            base.device.type != "cpu"
            or config._attn_implementation != "sdpa"
            or any(module.training for module in base.backbone.modules())
            or any(module.training for module in base.head.modules())
            or any(
                value.device.type != "cpu" or value.dtype != torch.float32
                for value in (*base.backbone.parameters(), *base.head.parameters())
            )
            or any(value.device.type != "cpu" for value in base.backbone.buffers())
            or base.backbone.has_sliding_layers
        ):
            raise ValueError("CPU prefix requires eval FP32 CPU SDPA full attention")
        if (
            not prefix
            or len(prefix) >= base.max_length
            or any(
                type(token) is not int or not 0 <= token < config.vocab_size
                for token in prefix
            )
        ):
            raise ValueError("Prefix requires valid nonempty tokens below max_length")
        self.base = base
        self.model_id = base.model_id
        self._prefix = prefix
        with torch.inference_mode():
            cache = new_cache(config=config)
            base.backbone(
                input_ids=torch.tensor([prefix], dtype=torch.long),
                past_key_values=cache,
                use_cache=True,
            )
            states: list[KVState] = []
            for layer in cache.layers:
                if not isinstance(layer, DynamicLayer):
                    raise ValueError(
                        "CPU prefix requires maintained DynamicLayer state"
                    )
                keys, values = layer.keys, layer.values
                if (
                    keys is None
                    or values is None
                    or keys.shape != values.shape
                    or tuple(keys.shape)
                    != (1, config.num_key_value_heads, len(prefix), config.head_dim)
                    or keys.dtype != torch.float32
                    or values.dtype != torch.float32
                    or keys.stride(-1) != 1
                    or values.stride(-1) != 1
                    or not torch.isfinite(keys).all().item()
                    or not torch.isfinite(values).all().item()
                ):
                    raise ValueError(
                        "Maintained cache did not retain exact FP32 prefix"
                    )
                states.append(
                    (
                        keys.detach().clone().contiguous(),
                        values.detach().clone().contiguous(),
                    )
                )
            if len(states) != config.num_hidden_layers:
                raise ValueError("Maintained cache omitted a prefix layer")
            self._states = tuple(states)

    @property
    def prefix(self) -> tuple[int, ...]:
        return self._prefix

    @property
    def prefix_state_bytes(self) -> int:
        return sum(
            value.numel() * value.element_size()
            for pair in self._states
            for value in pair
        )

    def admits(self, row: EncodedRequest) -> bool:
        length = len(self.prefix)
        return (
            len(row.ids) > length
            and row.ids[:length] == self.prefix
            and row.query_position >= length
            and all(position >= length for position in row.candidate_positions)
        )

    def fork(self, batch_size: int) -> DynamicCache:
        """Maintained update/cat allocates batch-private K/V from prefix views."""
        if type(batch_size) is not int or batch_size < 1:
            raise ValueError("Cache batch size must be a positive integer")
        states = tuple(
            (keys.expand(batch_size, -1, -1, -1), values.expand(batch_size, -1, -1, -1))
            for keys, values in self._states
        )
        return new_cache(config=self.base.backbone.config, ddp_cache_data=states)

    def score_many(self, requests: Sequence[Request]) -> list[list[float]]:
        if not requests:
            return []
        # Admission applies to the complete original input before prefix removal.
        encoded = [self.base.encode_request(request) for request in requests]
        if not all(self.admits(row) for row in encoded):
            return self.base.score_many(requests)
        prefix_length = len(self.prefix)
        batch_size = len(encoded)
        length = max(len(row.ids) for row in encoded) - prefix_length
        width = max(len(row.candidate_positions) for row in encoded)
        ids = torch.full((batch_size, length), self.base.pad_id, dtype=torch.long)
        endpoints = torch.zeros((batch_size, width), dtype=torch.long)
        for index, row in enumerate(encoded):
            suffix = row.ids[prefix_length:]
            ids[index, : len(suffix)] = torch.tensor(suffix, dtype=torch.long)
            endpoints[index, : len(row.candidate_positions)] = torch.tensor(
                [position - prefix_length for position in row.candidate_positions]
            )
        rows = torch.arange(batch_size)
        positions = torch.tensor(
            [row.query_position - prefix_length for row in encoded]
        )
        with torch.inference_mode():
            # Keep maintained offset mask/RoPE: rectangular is_causal alone is wrong.
            output = cast(
                BaseModelOutputWithPast,
                self.base.backbone(
                    input_ids=ids, past_key_values=self.fork(batch_size), use_cache=True
                ),
            )
            hidden = output.last_hidden_state
            if hidden is None:
                raise ValueError("Kai backbone did not return suffix hidden states")
            logits = cast(
                torch.Tensor,
                self.base.head(
                    hidden[rows[:, None], endpoints], hidden[rows, positions]
                ),
            )
            values = cast(list[list[float]], logits.float().cpu().tolist())
        return [
            row[: len(item.candidate_positions)]
            for row, item in zip(values, encoded, strict=True)
        ]

"""One common prefix path with retained or one-use maintained cache owners."""

from __future__ import annotations

from collections.abc import Callable, Sequence
from dataclasses import dataclass
from typing import Literal, cast

import torch
from transformers import Qwen3Config
from transformers.cache_utils import DynamicCache, DynamicLayer
from transformers.modeling_outputs import BaseModelOutputWithPast

from benchmarks.analysis.torch.prefix.cache import PrefixScorer
from benchmarks.analysis.torch.prefix.lifetime import OneUseCache
from wyat.backends.kai.torch import KaiScorer
from wyat.core import Request

type Arm = Literal["retained", "one-use"]
type KVState = tuple[torch.Tensor, torch.Tensor]


@dataclass(frozen=True)
class StorageObservation:
    layer: int | None
    cache_owned_bytes: int
    returned_logical_bytes: int
    combined_unique_storage_bytes: int


def storage_bytes(tensors: Sequence[torch.Tensor]) -> int:
    """Deduplicate actual underlying CPU allocations, including aliased views."""
    allocations = {
        (tensor.untyped_storage().data_ptr(), tensor.untyped_storage().nbytes())
        for tensor in tensors
    }
    return sum(size for _, size in allocations)


def observe_storage(
    cache: DynamicCache,
    seeds: tuple[KVState, ...],
    returned: KVState | None,
    layer: int | None,
) -> StorageObservation:
    owned: list[torch.Tensor] = []
    for state in cache.layers:
        if not isinstance(state, DynamicLayer):
            raise ValueError("Observer requires maintained DynamicLayer")
        owned.extend(
            tensor for tensor in (state.keys, state.values) if tensor is not None
        )
    current = list(returned or ())
    return StorageObservation(
        layer,
        storage_bytes(owned),
        sum(tensor.numel() * tensor.element_size() for tensor in current),
        storage_bytes(
            [*owned, *current, *(tensor for pair in seeds for tensor in pair)]
        ),
    )


type Observer = Callable[[StorageObservation], None]


class ObservedRetained(DynamicCache):
    """Intrusive memory-cycle owner only; ordinary calls use stock DynamicCache."""

    def __init__(
        self,
        config: Qwen3Config,
        states: tuple[KVState, ...],
        seeds: tuple[KVState, ...],
        observer: Observer,
    ) -> None:
        initialize = cast(Callable[..., None], super().__init__)
        initialize(config=config, ddp_cache_data=states)
        self.seeds, self.observer = seeds, observer
        observer(observe_storage(self, seeds, None, None))

    def update(
        self,
        key_states: torch.Tensor,
        value_states: torch.Tensor,
        layer_idx: int,
        *args: object,
        **kwargs: object,
    ) -> KVState:
        update = cast(Callable[..., KVState], super().update)
        returned = update(key_states, value_states, layer_idx, *args, **kwargs)
        self.observer(observe_storage(self, self.seeds, returned, layer_idx))
        return returned


class ObservedOneUse(OneUseCache):
    """Observe after maintained concatenation and one-use reference release."""

    def __init__(
        self,
        config: Qwen3Config,
        states: tuple[KVState, ...],
        seeds: tuple[KVState, ...],
        observer: Observer,
    ) -> None:
        super().__init__(config, states)
        self.seeds, self.observer = seeds, observer
        observer(observe_storage(self, seeds, None, None))

    def update(
        self,
        key_states: torch.Tensor,
        value_states: torch.Tensor,
        layer_idx: int,
        *args: object,
        **kwargs: object,
    ) -> KVState:
        returned = super().update(key_states, value_states, layer_idx, *args, **kwargs)
        self.observer(observe_storage(self, self.seeds, returned, layer_idx))
        return returned


class MemoryScorer(PrefixScorer):
    """Both arms suppress output cache, but keep their private owner through head.

    Prefix validation, snapshots and fallback reuse the frozen prefix scorer.
    Only cache factory/layer reference lifetime differs; neither returns a cache.
    Weights/config/device/encoder stay fixed and eval for this resource lifetime.
    """

    def __init__(self, base: KaiScorer, prefix: tuple[int, ...], arm: Arm) -> None:
        if arm not in ("retained", "one-use"):
            raise ValueError("Cache arm must be retained or one-use")
        super().__init__(base, prefix)
        self.arm = arm

    def fork(self, batch_size: int) -> DynamicCache:
        if type(batch_size) is not int or batch_size < 1:
            raise ValueError("Cache batch size must be a positive integer")
        if self.arm == "retained":
            return super().fork(batch_size)
        states = tuple(
            (keys.expand(batch_size, -1, -1, -1), values.expand(batch_size, -1, -1, -1))
            for keys, values in self._states
        )
        return OneUseCache(self.base.backbone.config, states)

    def score_many(self, requests: Sequence[Request]) -> list[list[float]]:
        return self.score_observed(requests)

    def score_observed(
        self,
        requests: Sequence[Request],
        observer: Observer | None = None,
    ) -> list[list[float]]:
        """Observer includes only cache/returned KV/immutable seeds, not all tensors.

        It runs only in a separate intrusive memory cycle. Returned KV remains
        counted after OneUse reset; callbacks retain numbers, never tensors.
        """
        if not requests:
            return []
        encoded = [self.base.encode_request(request) for request in requests]
        if not all(self.admits(row) for row in encoded):
            return self.base.score_many(requests)
        prefix_length = len(self.prefix)
        batch_size = len(encoded)
        length = max(len(row.ids) for row in encoded) - prefix_length
        width = max(len(row.candidate_positions) for row in encoded)
        ids = torch.full((batch_size, length), self.base.pad_id, dtype=torch.long)
        endpoints = torch.zeros((batch_size, width), dtype=torch.long)
        for index, row in enumerate(encoded):
            suffix = row.ids[prefix_length:]
            ids[index, : len(suffix)] = torch.tensor(suffix, dtype=torch.long)
            endpoints[index, : len(row.candidate_positions)] = torch.tensor(
                [position - prefix_length for position in row.candidate_positions]
            )
        rows = torch.arange(batch_size)
        positions = torch.tensor(
            [row.query_position - prefix_length for row in encoded]
        )
        with torch.inference_mode():
            if observer is None:
                owner = self.fork(batch_size)
            else:
                states = tuple(
                    (
                        keys.expand(batch_size, -1, -1, -1),
                        values.expand(batch_size, -1, -1, -1),
                    )
                    for keys, values in self._states
                )
                factory = ObservedRetained if self.arm == "retained" else ObservedOneUse
                owner = factory(
                    self.base.backbone.config, states, self._states, observer
                )
            output = cast(
                BaseModelOutputWithPast,
                self.base.backbone(
                    input_ids=ids, past_key_values=owner, use_cache=False
                ),
            )
            if output.past_key_values is not None or (
                isinstance(owner, OneUseCache) and not owner.consumed
            ):
                raise ValueError(
                    "Private cache must be consumed without returned state"
                )
            hidden = output.last_hidden_state
            if hidden is None:
                raise ValueError("Kai backbone did not return suffix hidden states")
            logits = cast(
                torch.Tensor,
                self.base.head(
                    hidden[rows[:, None], endpoints], hidden[rows, positions]
                ),
            )
            values = cast(list[list[float]], logits.float().cpu().tolist())
        return [
            row[: len(item.candidate_positions)]
            for row, item in zip(values, encoded, strict=True)
        ]

