        (63, 65, 31),
        (64, 64, 32),
        (65, 63, 33),
        (129, 127, 97),
        (77, 99, 64),
    ],
)
def test_tail_rows_columns_and_reduction(
    kernels: Kernels, rows: int, columns: int, reduction: int
) -> None:
    check_projection(kernels, rows, columns, reduction)


