"""Frozen-input checks and measurement order, independent of tensor execution."""

from __future__ import annotations

import json
from collections import Counter
from pathlib import Path

import pytest
from hypothesis import given
from hypothesis import strategies as st

from benchmarks.analysis.reference import balanced_orders, read_reference
from wyat.backends.kai.encoding import EncodedRequest
from wyat.core import Candidate, Request
from wyat.evaluation import EvaluationCase


class Encoder:
    model_id = "test-artifact"

    def encode_request(self, request: Request) -> EncodedRequest:
        return EncodedRequest((1, 2, 3, 4), (1, 2), 3)


@given(
    st.lists(st.integers(1, 100), min_size=1, max_size=8, unique=True),
    st.integers(1, 4),
)
def test_rotations_balance_every_load_position(loads: list[int], rounds: int) -> None:
    orders = balanced_orders(loads, len(loads) * rounds)
    assert all(set(order) == set(loads) for order in orders)
    for position in range(len(loads)):
        assert Counter(order[position] for order in orders) == Counter(
            {load: rounds for load in loads}
        )


@pytest.mark.parametrize(
    "loads,repeats", [([], 6), ([1, 1], 2), ([0], 1), ([1, 2, 4], 2), ([1, 2], 3)]
)
def test_invalid_order_is_rejected(loads: list[int], repeats: int) -> None:
    with pytest.raises(ValueError):
        balanced_orders(loads, repeats)


def _case() -> EvaluationCase:
    return EvaluationCase(
        "one", Request("route", (Candidate("a", "A"), Candidate("b", "B"))), ("b",)
    )


def _document() -> dict[str, object]:
    return {
        "model_id": "test-artifact",
        "dataset_sha256": "declared",
        "rows": [
            {
                "id": "one",
                "candidate_ids": ["a", "b"],
                "token_ids": [1, 2, 3, 4],
                "candidate_positions": [1, 2],
                "query_position": 3,
                "legacy_logits": [-1.0, 1.0],
            }
        ],
    }


def test_reference_checks_tokens_and_reconstructs_decision(tmp_path: Path) -> None:
    path = tmp_path / "reference.json"
    path.write_text(json.dumps(_document()))
    cycle = read_reference(path, (_case(),), Encoder(), dataset_sha256="declared")
    assert cycle.correct == 1
    assert cycle.failed == 0
    assert cycle.rows[0].prediction is not None
    assert cycle.rows[0].prediction.ranking == ("b", "a")


@pytest.mark.parametrize(
    "field,replacement",
    [
        ("token_ids", [1, 2, 9, 4]),
        ("candidate_positions", [2, 1]),
        ("candidate_ids", ["b", "a"]),
        ("query_position", 2),
    ],
)
def test_reference_rejects_input_drift(
    tmp_path: Path, field: str, replacement: object
) -> None:
    document = _document()
    rows = document["rows"]
    assert isinstance(rows, list)
    rows[0][field] = replacement
    path = tmp_path / "reference.json"
    path.write_text(json.dumps(document))
    with pytest.raises(ValueError, match="Reference inputs differ"):
        read_reference(path, (_case(),), Encoder(), dataset_sha256="declared")

"""Cross-runtime oracles; seeded fixtures establish mechanics, not quality."""

from __future__ import annotations

import subprocess
import sys
from collections.abc import Sequence
from pathlib import Path

import pytest
from hypothesis import HealthCheck, given, settings
from hypothesis import strategies as st

mx = pytest.importorskip("mlx.core")
pytest.importorskip("mlx_lm")
torch = pytest.importorskip("torch")

from benchmarks.fixtures.kai import create_kai_bundle  # noqa: E402
from wyat import Candidate, Request  # noqa: E402
from wyat.backends.kai.mlx import MLXCandidateHead, MLXKaiScorer  # noqa: E402
from wyat.backends.kai.torch import CandidateHead, KaiScorer  # noqa: E402


@pytest.fixture
def bundle(tmp_path: Path) -> Path:
    return create_kai_bundle(tmp_path / "kai")


@pytest.fixture(params=["cpu", "gpu"])
def native(bundle: Path, request: pytest.FixtureRequest) -> MLXKaiScorer:
    device = str(request.param)
    if device == "gpu" and not mx.metal.is_available():
        pytest.skip("Metal GPU is unavailable")
    return MLXKaiScorer.from_directory(bundle, max_length=512, device=device)


def request(texts: Sequence[str], context: str = "Bonjour") -> Request:
    return Request(
        query="read?",
        context=context,
        candidates=tuple(
            Candidate(str(index), text) for index, text in enumerate(texts)
        ),
    )


@given(rows=st.integers(1, 3), choices=st.integers(2, 6), seed=st.integers(0, 30))
@settings(max_examples=12, deadline=None)
def test_fp32_head_matches_torch(rows: int, choices: int, seed: int) -> None:
    with torch.random.fork_rng():
        torch.manual_seed(seed)
        reference = CandidateHead(16, 8).eval()
        candidates = torch.randn(rows, choices, 16)
        query = torch.randn(rows, 16)
    with mx.stream(mx.cpu):
        head = MLXCandidateHead(16, 8)
        head.load_weights(
            [
                (name, mx.array(value.numpy()))
                for name, value in reference.state_dict().items()
            ],
            strict=True,
        )
        actual = head(mx.array(candidates.numpy()), mx.array(query.numpy()))
        mx.eval(actual)
        values = actual.tolist()
    with torch.inference_mode():
        expected = reference(candidates, query)
    torch.testing.assert_close(torch.tensor(values), expected, atol=1e-6, rtol=1e-5)


def test_local_bundle_matches_torch_tokenizer_and_logits(
    native: MLXKaiScorer,
    bundle: Path,
) -> None:
    reference = KaiScorer.from_directory(bundle, max_length=512)
    values = [request(("yes", "no")), request(("世界", "é", "a"), "write " * 7)]
    assert native.model_id == reference.model_id
    assert [native.encode_request(value) for value in values] == [
        reference.encode_request(value) for value in values
    ]
    for actual, expected in zip(
        native.score_many(values), reference.score_many(values), strict=True
    ):
        assert actual == pytest.approx(expected, abs=2e-6, rel=1e-5)
    assert native.score_many([]) == []


@given(
    texts=st.lists(
        st.text(alphabet='abc 世界é\n<>/"\\', min_size=1, max_size=20).filter(
            str.strip
        ),
        min_size=2,
        max_size=5,
    ),
)
@settings(
